//! 🌐️ Public lifecycle laws use the same staged source, finite CPU and controlled return ports as production.
use semio_framework_value_retained_clone::*;
use semio_framework_value_clone_source::{RetainedCloneSource,RetainedCloneBorrowAuthority,RetainedCloneBinding,RetainedCloneSourceTake};
use semio_framework_value_testing_allocator::observe_retirement_allocations as observe;
use semio_framework_value_retirement::retirement;
fn grant(d:RetirementDemand)->RetainedCloneGrant{RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:d.copy_bytes,maximum_capacity_bytes:d.capacity_bytes,maximum_release_bytes:d.release_bytes,maximum_depth:d.depth}}
fn debit(work:u64,cpu:&mut u64){*cpu=cpu.checked_sub(work).expect("same explicit finite lifecycle CPU bank")}
fn progress(p:RetainedCloneProgress,g:RetainedCloneGrant,h:(usize,usize),totals:&mut(usize,usize)){assert!(p.fits(g));assert_eq!(h,(p.retained_capacity_bytes,p.released_bytes));totals.0+=h.0;totals.1+=h.1;}
fn open<T:RetainedClone>(value:T,cpu:&mut u64,totals:&mut(usize,usize))->RetainedCloneSource<T>{let(mut admission,h)=observe(||RetainedCloneSource::<T>::admission_owned(value,()));assert_eq!(h,(0,0));let mut out=None;for _ in 0..512{if admission.terminal_is_empty(){break}let g=grant(admission.next_demand().unwrap());let q=if admission.phase()=="ready"{1}else{admission.advance_work_demand().unwrap()};assert!(q<=*cpu);let mut actual=None;let(t,h)=observe(||if admission.phase()=="ready"{admission.take_output(&mut out,g)}else{admission.advance(g,&mut actual)});assert!(t.work<=q);debit(t.work,cpu);if let Some(bytes)=actual{assert_eq!(bytes,h.0)}progress(t.result.unwrap().progress(),g,h,totals);}assert!(admission.terminal_is_empty());out.unwrap()}
fn start<T:RetainedClone>(cursor:&mut impl RetainedCloneCursor<T>,cpu:&mut u64){let q=cursor.begin_close_work_demand().unwrap();assert!(q<=*cpu);let(t,h)=observe(||cursor.begin_close_paid());assert_eq!(t.work,q);debit(t.work,cpu);t.result.unwrap();assert_eq!(h,(0,0));}
fn close<T:RetainedClone>(cursor:&mut impl RetainedCloneCursor<T>,cpu:&mut u64,totals:&mut(usize,usize),limit:usize){start(cursor,cpu);for n in 0..limit{if cursor.terminal_is_empty(){break}let d=cursor.close_demands(4096).unwrap();let q=cursor.close_work_demand(4096).unwrap();assert!(q<=*cpu);let g=grant(d);assert_eq!(cursor.close_demands(g.maximum_copy_bytes).unwrap(),d);let(t,h)=observe(||cursor.close_step(g));assert!(t.work<=q);debit(t.work,cpu);progress(t.result.unwrap().progress(),g,h,totals);assert!(n+1<limit||cursor.terminal_is_empty());}assert!(cursor.terminal_is_empty());}
fn close_source<T:RetainedClone>(source:&mut RetainedCloneSource<T>,body:usize,cpu:&mut u64,totals:&mut(usize,usize),limit:usize){for n in 0..limit{if source.terminal_is_empty(){break}let d=source.next_close_demand(body).unwrap();let q=source.next_close_work_demand(body).unwrap();assert!(q<=*cpu);let g=grant(d);assert_eq!(source.next_close_demand(g.maximum_copy_bytes).unwrap(),d);let(t,h)=observe(||source.close_step(g));assert!(t.work<=q);debit(t.work,cpu);progress(t.result.unwrap().progress(),g,h,totals);assert!(n+1<limit||source.terminal_is_empty());}assert!(source.terminal_is_empty());}
fn close_value<T:RetainedClone>(value:T,cpu:&mut u64,totals:&mut(usize,usize)){let mut slot=Some(value);let mut close=RetainedCloneClose::default();for n in 0..10000{if slot.is_none()&&close.is_empty(){break}let d=close.next_owner_demands::<T>(slot.is_some(),&None,4096).unwrap();let q=close.next_owner_work::<T>(slot.is_some(),&None,4096).unwrap();assert!(q<=*cpu);let g=grant(d);let(t,h)=observe(||if close.is_empty(){let t=close.begin_granted(&mut slot,g);RetainedWorkOutcome{result:t.result.map(|s|s.unwrap_or(RetainedCloneStep::Progress(Default::default()))).map_err(Into::into),work:t.work}}else{close.step_granted(g)});assert!(t.work<=q);debit(t.work,cpu);progress(t.result.unwrap().progress(),g,h,totals);assert!(n<9999);}assert!(slot.is_none()&&close.is_empty());}
#[test]fn scalar_output_and_selected_close_preserve_each_lifecycle(){for take in[false,true]{let mut cpu=1000000;let mut totals=(0,0);let mut source=open(42u64,&mut cpu,&mut totals);let original=source.borrow().get()as*const u64;let mut cursor=u64::retained_clone_cursor();for _ in 0..4{if cursor.output_ready(){break}let d=cursor.advance_demands(8,64).unwrap();let q=cursor.advance_work_demand(8,64).unwrap();let g=grant(d);let mut actual=None;let(t,h)=observe(||cursor.advance(source.borrow(),8,64,g,&mut actual));assert!(actual.is_none());assert!(t.work<=q);debit(t.work,&mut cpu);progress(t.result.unwrap().progress(),g,h,&mut totals);}assert!(cursor.output_ready());if take{let g=grant(cursor.take_demand().unwrap());let(t,h)=observe(||cursor.take(g));assert_eq!(t.work,1);debit(t.work,&mut cpu);let(value,p)=t.result.unwrap().unwrap();progress(p,g,h,&mut totals);assert_eq!(value,42);close_value(value,&mut cpu,&mut totals);}start(&mut cursor,&mut cpu);assert!(!cursor.output_ready());assert!(cursor.take(Default::default()).result.unwrap().is_none());close(&mut cursor,&mut cpu,&mut totals,64);assert_eq!(source.borrow().get()as*const u64,original);assert_eq!(observe(||drop(cursor)).1,(0,0));close_source(&mut source,4096,&mut cpu,&mut totals,128);assert_eq!(observe(||drop(source)).1,(0,0));assert_eq!(totals.0,totals.1);}}
#[test]fn scalar_compounds_preserve_selected_close_and_single_output_custody(){
 fn check<T:RetainedClone+Clone+PartialEq+std::fmt::Debug+serde::Serialize>(original:T){for taken in[false,true]{let expected=serde_json::to_value(&original).unwrap();let(payload,h)=observe(||original.clone());let mut totals=h;let mut cpu=1000000;let mut source=open(payload,&mut cpu,&mut totals);let mut cursor=T::retained_clone_cursor();for n in 0..128{if cursor.output_ready(){break}let d=cursor.advance_demands(source.borrow(),4096,4096).unwrap();let g=grant(d);let q=cursor.advance_work_demand(source.borrow(),4096,4096).unwrap();assert!(q<=4096&&q<=cpu);let(t,h)=observe(||cursor.advance(source.borrow(),4096,4096,g));assert!(t.work<=q);debit(t.work,&mut cpu);progress(t.result.unwrap().progress(),g,h,&mut totals);assert!(n<127);}assert!(cursor.output_ready());if taken{let g=grant(cursor.take_demand().unwrap());let(t,h)=observe(||cursor.take(g));debit(t.work,&mut cpu);let(value,p)=t.result.unwrap().unwrap();progress(p,g,h,&mut totals);assert_eq!(value,original);assert_eq!(serde_json::to_value(&value).unwrap(),expected);close_value(value,&mut cpu,&mut totals);}start(&mut cursor,&mut cpu);assert!(!cursor.output_ready());assert!(cursor.take(Default::default()).result.unwrap().is_none());close(&mut cursor,&mut cpu,&mut totals,512);assert_eq!(observe(||drop(cursor)).1,(0,0));close_source(&mut source,4096,&mut cpu,&mut totals,1024);assert_eq!(observe(||drop(source)).1,(0,0));assert_eq!(totals.0,totals.1);}}
 let law:serde_json::Value=serde_json::from_str(include_str!("../🧫️fixtures/🔣️.json")).unwrap();for kind in law["compounds"].as_array().unwrap(){match kind.as_str().unwrap(){"scalar-vector"=>check(vec![0u64,42,u64::MAX]),"owned-vector"=>check(vec!["α".to_owned(),String::new()]),"optional-scalar"=>check(Some(42u64)),"optional-vector"=>check(Some(vec![0u8,42,255])),"empty-option"=>check(Option::<u64>::None),"boxed-scalar"=>check(Box::new(42u64)),"boxed-owned"=>check(Box::new("α".to_owned())),"tuple"=>check(("α".to_owned(),42u64)),_=>panic!("closed compound fixture kind")}}
}
#[test]fn composite_close_quotes_its_own_child_start_before_the_child_close_protocol(){
 static ADVANCES:std::sync::atomic::AtomicUsize=std::sync::atomic::AtomicUsize::new(0);
 struct StrictAtom;struct StrictCursor{closing:bool}
 impl retirement::RetireOwned for StrictAtom{fn retirement(self)->Box<dyn retirement::RetirementCursor>{retirement::RetireOwned::retirement(())}fn retirement_birth_bytes(&self)->Option<usize>{<()as retirement::RetireOwned>::retirement_birth_bytes(&())}fn controlled_retirement_supported()->bool{true}}
 impl RetainedClone for StrictAtom{type Cursor=StrictCursor;fn retained_clone_cursor()->Self::Cursor{StrictCursor{closing:false}}}
 impl RetainedCloneCursor<StrictAtom> for StrictCursor{
 fn advance_demands(&self,_:RetainedCloneRef<'_,StrictAtom>,_:usize,work:u64)->Result<RetirementDemand,ValueError>{assert!(!self.closing);Ok(RetirementDemand{depth:usize::from(work>0),..Default::default()})}
 fn advance_work_demand(&self,s:RetainedCloneRef<'_,StrictAtom>,b:usize,w:u64)->Result<u64,ValueError>{self.advance_demands(s,b,w)?;Ok(u64::from(w>0))}
 fn advance(&mut self,_:RetainedCloneRef<'_,StrictAtom>,_:usize,w:u64,g:RetainedCloneGrant)->OriginalRetirementOutcome{assert!(!self.closing);let admitted=w>0&&g.maximum_items>0&&g.maximum_depth>0;if admitted{ADVANCES.fetch_add(1,std::sync::atomic::Ordering::SeqCst);}RetainedWorkOutcome{result:Ok(RetainedCloneStep::Progress(RetainedCloneProgress{copied_items:usize::from(admitted),..Default::default()})),work:u64::from(admitted)}}
 fn take_demand(&self)->Result<RetirementDemand,ValueError>{Ok(Default::default())}fn take_work_demand(&self)->Result<u64,ValueError>{Ok(0)}fn take(&mut self,_:RetainedCloneGrant)->RetainedWorkOutcome<Option<(StrictAtom,RetainedCloneProgress)>>{RetainedWorkOutcome{result:Ok(None),work:0}}
 fn begin_close(&mut self)->bool{let changed=!self.closing;self.closing=true;changed}fn begin_close_work_demand(&self)->Result<u64,ValueError>{Ok(u64::from(!self.closing))}fn begin_close_paid(&mut self)->RetainedWorkOutcome<(),ValueError>{let changed=self.begin_close();RetainedWorkOutcome{result:Ok(()),work:u64::from(changed)}}fn close_started(&self)->bool{self.closing}
 fn terminal_is_empty(&self)->bool{self.closing}fn next_close_depth_demand(&self)->Result<usize,ValueError>{Ok(usize::from(self.closing))}fn close_demands(&self,_:usize)->Result<RetirementDemand,ValueError>{assert!(self.closing,"parent queried an unstarted close protocol");Ok(RetirementDemand{depth:1,..Default::default()})}fn close_work_demand(&self,_:usize)->Result<u64,ValueError>{assert!(self.closing);Ok(0)}fn close_step(&mut self,_:RetainedCloneGrant)->OriginalRetirementOutcome{assert!(self.closing);RetainedWorkOutcome{result:Ok(RetainedCloneStep::Complete(Default::default())),work:0}}
 }
 fn inspect<T:RetainedClone>(value:T,mut cursor:impl RetainedCloneCursor<T>){let mut cpu=1000000;let mut totals=(0,0);let mut source=open(value,&mut cpu,&mut totals);let before=ADVANCES.load(std::sync::atomic::Ordering::SeqCst);for n in 0..128{if ADVANCES.load(std::sync::atomic::Ordering::SeqCst)!=before{break}let d=cursor.advance_demands(source.borrow(),4096,4096).unwrap();let g=grant(d);let q=cursor.advance_work_demand(source.borrow(),4096,4096).unwrap();assert!(q<=cpu&&q<=4096);let(t,h)=observe(||cursor.advance(source.borrow(),4096,4096,g));assert!(t.work<=q);debit(t.work,&mut cpu);progress(t.result.unwrap().progress(),g,h,&mut totals);assert!(n<127);}assert!(ADVANCES.load(std::sync::atomic::Ordering::SeqCst)>before);start(&mut cursor,&mut cpu);assert!(cursor.advance_demands(source.borrow(),4096,4096).is_err());let d=cursor.close_demands(4096).unwrap();assert_eq!(d.depth,1);assert_eq!(d.capacity_bytes,0);assert_eq!(d.release_bytes,0);let(t,h)=observe(||cursor.close_step(RetainedCloneGrant{maximum_items:0,maximum_depth:1,..Default::default()}));assert_eq!(h,(0,0));assert_eq!(t.result.unwrap().progress(),Default::default());close(&mut cursor,&mut cpu,&mut totals,512);close_source(&mut source,4096,&mut cpu,&mut totals,128);}
 inspect(Some(StrictAtom),Option::<StrictAtom>::retained_clone_cursor());inspect(vec![StrictAtom],Vec::<StrictAtom>::retained_clone_cursor());inspect([StrictAtom,StrictAtom],<[StrictAtom;2]>::retained_clone_cursor());inspect(Box::new(StrictAtom),Box::<StrictAtom>::retained_clone_cursor());inspect((StrictAtom,StrictAtom),<(StrictAtom,StrictAtom)>::retained_clone_cursor());inspect(StrictAtom,RetainedFieldCursor::<StrictAtom>::default());let mut paged=semio_framework_value_paged_list::list::PagedList::<StrictAtom,1>::default();while !paged.has_reserved_slot(){let bytes=paged.next_allocation_bytes().unwrap();assert!(paged.reserve_one(bytes).unwrap().progressed)}paged.push_reserved(StrictAtom).unwrap_or_else(|_|panic!("strict child fixture placement"));inspect(paged,<semio_framework_value_paged_list::list::PagedList<StrictAtom,1>>::retained_clone_cursor());
}
#[test]fn borrow_authority_handback_selects_one_event_and_preserves_original_custody(){
 let policy:serde_json::Value=serde_json::from_str(include_str!("../../../🧬️contract/🧪️tests/♻️close/🎯️dispatch/🧫️fixtures/🔣️.json")).unwrap();for body in policy["bodies"].as_array().unwrap(){let body=body.as_u64().unwrap()as usize;let mut cpu=1000000;let(original,h)=observe(||"original handback 🎟️".to_owned());let pointer=original.as_ptr();let mut totals=h;let mut opening=RetainedCloneBorrowAuthority::admission(original);let mut authority=None;for n in 0..128{if opening.terminal_is_empty(){break}let g=grant(opening.next_demand().unwrap());assert!(cpu>=3);let mut actual=None;let(t,h)=observe(||opening.advance(g,&mut actual));if let Some(bytes)=actual{assert_eq!(bytes,h.0)}assert!(t.work<=2);debit(t.work,&mut cpu);progress(t.result.unwrap().progress(),g,h,&mut totals);let(t,h)=observe(||opening.take_output(&mut authority,g));debit(t.work,&mut cpu);progress(t.result.unwrap().progress(),g,h,&mut totals);assert!(n<127);}assert!(opening.terminal_is_empty());let mut authority=authority.unwrap();let mut alias=None;let g=RetainedCloneGrant{maximum_items:1,maximum_depth:1,..Default::default()};let(t,h)=observe(||authority.borrow(1,|v|v).bind(&mut alias,g));debit(t.work,&mut cpu);if let Some(p)=t.result.unwrap(){progress(p,g,h,&mut totals)}else{assert_eq!(h,(0,0))}assert_eq!(authority.borrow(1,|v|v).get().as_ptr(),pointer);
 for n in 0..policy["maximumTurns"].as_u64().unwrap(){if alias.is_none(){break}let d=RetainedCloneBinding::close_demand(&alias,body).unwrap();let q=RetainedCloneBinding::close_work_demand(&alias,body).unwrap();assert!(q<=cpu);let g=grant(d);assert_eq!(RetainedCloneBinding::close_demand(&alias,g.maximum_copy_bytes).unwrap(),d);let(t,h)=observe(||RetainedCloneBinding::close_one(&mut alias,g));assert!(t.work<=q);debit(t.work,&mut cpu);progress(t.result.unwrap().progress(),g,h,&mut totals);assert!(n+1<policy["maximumTurns"].as_u64().unwrap()||alias.is_none());}assert!(alias.is_none());
 let mut output=None;for n in 0..policy["maximumTurns"].as_u64().unwrap(){let d=authority.next_take_demands(body).unwrap();let g=grant(d);assert_eq!(authority.next_take_demands(g.maximum_copy_bytes).unwrap(),d);let cuts=[Some(RetainedCloneGrant{maximum_items:0,..g}),d.copy_bytes.checked_sub(1).map(|maximum_copy_bytes|RetainedCloneGrant{maximum_copy_bytes,..g}),d.capacity_bytes.checked_sub(1).map(|maximum_capacity_bytes|RetainedCloneGrant{maximum_capacity_bytes,..g}),d.release_bytes.checked_sub(1).map(|maximum_release_bytes|RetainedCloneGrant{maximum_release_bytes,..g}),d.depth.checked_sub(1).map(|maximum_depth|RetainedCloneGrant{maximum_depth,..g})];for denied in cuts.into_iter().flatten(){let(t,h)=observe(||authority.take_authority(denied));assert_eq!(h,(0,0));assert_eq!(t.work,0);match t.result{Ok(RetainedCloneSourceTake::Pending(p))=>assert_eq!(p,Default::default()),Err(_)=>{},Ok(RetainedCloneSourceTake::Ready(..))=>panic!("underfunded authority transfer")};assert_eq!(authority.next_take_demands(body).unwrap(),d);}let(t,h)=observe(||authority.take_authority(g));debit(t.work,&mut cpu);let p=match t.result.unwrap(){RetainedCloneSourceTake::Pending(p)=>p,RetainedCloneSourceTake::Ready(value,p)=>{assert_eq!(value.as_ptr(),pointer);assert_eq!(value,"original handback 🎟️");output=Some(value);p}};progress(p,g,h,&mut totals);if output.is_some(){break}assert!(n+1<policy["maximumTurns"].as_u64().unwrap());}assert!(authority.terminal_is_empty());close_value(output.unwrap(),&mut cpu,&mut totals);assert_eq!(observe(||drop(authority)).1,(0,0));assert_eq!(totals.0,totals.1);}
}
